catalog_script_client.script:
function onSubmit() {
    //fetching date value from field return_datetime
    var returndateValue = g_form.getValue('return_datetime');

    //allowing submission if field is empty 
    if (!returndateValue) {
        return true;
    }

    //replacing space with 'T' so browser can convert it properly
    var formattedReturnDate = returndateValue.replace(' ', 'T');

    //converting it into date only
    var selectedreturnDateTime = new Date(formattedReturnDate);

    //fetching date value from field pickup_datetime
    var pickupdateValue = g_form.getValue('pickup_datetime');

    //allowing submission if field is empty 
    if (!pickupdateValue) {
        return true;
    }

    //replacing space with 'T' so browser can convert it properly
    var formattedPickupDate = pickupdateValue.replace(' ', 'T');

    //converting it into date only
    var selectedPickupDateTime = new Date(formattedPickupDate);

    if (isNaN(selectedreturnDateTime.getTime()) || isNaN(selectedPickupDateTime.getTime())) {
        g_form.addErrorMessage('Please enter a valid date and time.');
        return false;
    }

    //calculating minimum allowed return time (at least 6 hours after pickup)
    var minReturnTime = new Date(selectedPickupDateTime.getTime() + (6 * 60 * 60 * 1000));

    //now comparing return_datetime and pickup_datetime if return_datetime is not at least 6 hours after pickup_datetime do not let form submit
    if (selectedreturnDateTime < minReturnTime) {
        g_form.addErrorMessage('The return date and time must be at least 6 hours after the pickup date and time.');
        return false;
    }
}
